practice.solution:
@* Clock.razor *@
@implements IDisposable

<p>Seconds: @seconds</p>

@code {
    private int seconds;
    private Timer? timer;

    protected override void OnInitialized()
    {
        timer = new Timer(_ =>
        {
            seconds++;
            InvokeAsync(StateHasChanged);
        }, null, 1000, 1000);
    }

    public void Dispose()
    {
        timer?.Dispose();
    }
}

@page "/report"
@implements IDisposable
@inject ReportService Service

@if (report is null)
{
    <p>Loading...</p>
}
else
{
    <p>@report</p>
}

@code {
    private readonly CancellationTokenSource cts = new();
    private string? report;

    protected override async Task OnInitializedAsync()
    {
        report = await Service.GetReportAsync(cts.Token);
    }

    public void Dispose()
    {
        cts.Cancel();
        cts.Dispose();
    }
}

